// ============================================================================
// INTERVIEW BANK — content for the AI Interview Simulator (data only; logic is in interviewEngine.js).
// A *concept* is something a good answer should mention:  cpt(name, "kw1|kw2|kw3", hint)
// Answers are scored by how many concepts they cover (keyword evidence), plus structure/clarity checks.
// Skill interview questions chain upward: Basic → Intermediate → Advanced of the same skill become the
// adaptive follow-ups (e.g. "What is EC2?" → "stop vs terminate?" → "how do you secure it in production?").
// ============================================================================
const cpt = (name, kw, hint, weight = 1) => ({ name, kw: kw.split("|"), hint, weight });
const iq = (topic, q, concepts, ideal) => ({ topic, q, concepts, ideal });

// ---- Curated technical-skill interview questions (per skill, per level) ----
