    intermediate: iq("AWS / EC2", "What is the difference between stopping and terminating an EC2 instance?", [cpt("stop keeps the instance", "stop.{0,40}(keep|retain|persist|preserv|restart|start again)|(keep|retain|persist).{0,40}stop", "A stopped instance can be started again and its EBS volumes persist."), cpt("terminate deletes it", "terminat.{0,50}(delet|destroy|gone|permanent|cannot|can't|remov)|(delet|destroy|permanent).{0,40}terminat", "Termination permanently deletes the instance; it cannot be restarted."), cpt("storage effects", "ebs|volume|instance store|data", "EBS volumes can persist; instance-store data is lost on stop/terminate."), cpt("billing", "bill|charge|cost|pay", "You stop paying for compute while stopped (storage is still billed).")], "Stopping shuts the instance down but keeps it and its EBS volumes so it can be restarted (no compute charges). Terminating deletes the instance permanently, and the root volume is deleted by default."),
